    "summary": "To explain the difference between the two learning theories, this approach contrasts them across four main dimensions: the nature of the behavior, the mechanism of learning, the timing of the stimulus, and real-world examples.",
    "classical_conditioning": {
      "definition": "Learning through association, where a neutral stimulus is paired with an unconditioned stimulus to eventually trigger a conditioned response.",
      "key_theorist": "Ivan Pavlov",
      "nature_of_behavior": "Involuntary, automatic, and reflexive (e.g., salivating, flinching, heart rate).",
      "mechanism": "The subject learns to associate two stimuli together.",
      "timing_of_stimulus": "The stimulus occurs BEFORE the response (antecedent).",
      "example": "Pavlov's dogs learning to salivate at the sound of a bell because the bell was repeatedly paired with food."
    },
    "operant_conditioning": {
      "definition": "Learning through consequences, where the frequency of a voluntary behavior is modified by reinforcement (increasing the behavior) or punishment (decreasing the behavior).",
      "key_theorist": "B.F. Skinner",
      "nature_of_behavior": "Voluntary and intentional (e.g., studying, pressing a lever, opening a door).",
      "mechanism": "The subject learns to associate a behavior with its consequence.",
      "timing_of_stimulus": "The consequence occurs AFTER the response.",
      "example": "A rat learning to press a lever in a Skinner box because the action is followed by a food pellet (positive reinforcement)."
    },
    "key_differences": [
      "Behavior Type: Classical conditioning involves involuntary/reflexive behaviors, whereas operant conditioning involves voluntary/purposeful behaviors.",
      "Temporal Relationship: In classical conditioning, the stimulus precedes the behavior. In operant conditioning, the consequence follows the behavior.",
      "Learner's Role: In classical conditioning, the learner is passive and simply reacts to stimuli. In operant conditioning, the learner is active and operates on the environment to produce consequences."
    ]
  }
}
