  "response": {
    "stack": {
      "definition": "A stack is a linear data structure that follows the LIFO (Last In, First Out) principle. The last element added is the first one to be removed.",
      "operations": [
        "push(item) - adds an element to the top of the stack",
        "pop() - removes and returns the top element",
        "peek()/top() - returns the top element without removing it",
        "isEmpty() - checks if the stack is empty"
      ],
      "access_point": "Insertion and deletion happen at only one end, called the 'top'.",
      "use_case": {
        "title": "Function Call Stack (Recursion Handling)",
        "description": "When a program calls a function, the calling function's state (local variables, return address) is pushed onto the call stack. When the called function completes, its state is popped off, and execution resumes in the caller. This LIFO behavior is essential for recursion, undo/redo features in editors, browser back-button history, and expression evaluation (e.g., converting infix to postfix)."
      }
    },
    "queue": {
      "definition": "A queue is a linear data structure that follows the FIFO (First In, First Out) principle. The first element added is the first one to be removed.",
      "operations": [
        "enqueue(item) - adds an element to the rear of the queue",
        "dequeue() - removes and returns the front element",
        "front()/peek() - returns the front element without removing it",
        "isEmpty() - checks if the queue is empty"
      ],
      "access_point": "Insertion happens at the 'rear' end, and deletion happens at the 'front' end.",
      "use_case": {
        "title": "Printer Job Scheduling / Task Queues",
        "description": "Print jobs sent to a shared printer are processed in the order they arrive — the first document submitted is the first one printed. This FIFO behavior ensures fairness. Queues are also widely used in BFS (Breadth-First Search) algorithms, CPU process scheduling, request handling in web servers, and message broker systems like RabbitMQ or Kafka."
      }
    },
    "key_differences": [
      {
        "aspect": "Ordering Principle",
        "stack": "LIFO - Last In, First Out",
        "queue": "FIFO - First In, First Out"
      },
      {
        "aspect": "Insertion/Removal Ends",
        "stack": "Both occur at the same end (top)",
        "queue": "Insertion at rear, removal at front"
      },
      {
        "aspect": "Primary Operations",
        "stack": "push() and pop()",
        "queue": "enqueue() and dequeue()"
      },
      {
        "aspect": "Typical Use Cases",
        "stack": "Recursion, undo/redo, backtracking, expression parsing",
